16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * The single derived duplicate-detection key for an owner: the lower-case SHA-256 hex digest over the
24	 * normalized telephone, the lower-case email (or empty) and the {@link #soundex soundex} of the last
25	 * name, joined with '|'. Two owners are duplicates only when this whole key matches.
26	 */
27	public final class OwnerIdentity {
28	
29	    /** Soundex code for each letter A-Z (index c - 'A'); '0' means "not coded". */
30	    private static final String SOUNDEX_CODES = "01230120022455012623010202";
31	
32	    private OwnerIdentity() {
33	    }
34	
35	    public static String key(Owner owner) {
36	        String email = owner.getEmail();
37	        String source = owner.getTelephone() + "|" + (email == null ? "" : email.toLowerCase())
38	            + "|" + soundex(owner.getLastName());
39	        StringBuilder sb = new StringBuilder();
40	        for (byte b : sha256(source)) {
41	            sb.append(String.format("%02x", b));
42	        }
43	        return sb.toString();
44	    }
45	
46	    /** The American Soundex code (a letter followed by three digits) for the given name, or empty. */
47	    static String soundex(String name) {
48	        String letters = name == null ? "" : name.toUpperCase().replaceAll("[^A-Z]", "");
49	        if (letters.isEmpty()) {
50	            return "";
51	        }
52	        StringBuilder sb = new StringBuilder().append(letters.charAt(0));
53	        char prev = SOUNDEX_CODES.charAt(letters.charAt(0) - 'A');
54	        for (int i = 1; i < letters.length() && sb.length() < 4; i++) {
55	            char c = letters.charAt(i);
56	            char code = SOUNDEX_CODES.charAt(c - 'A');
57	            if (code != '0' && code != prev) {
58	                sb.append(code);
59	            }
60	            if (c != 'H' && c != 'W') {
61	                prev = code;
62	            }
63	        }
64	        while (sb.length() < 4) {
65	            sb.append('0');
66	        }
67	        return sb.toString();
68	    }
69	
70	    private static byte[] sha256(String value) {
71	        try {
72	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
73	        } catch (NoSuchAlgorithmException e) {
74	            throw new IllegalStateException(e);
75	        }
76	    }
77	}
