1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes the Luhn check digit (0-9) over the decimal digits contained in a string, ignoring any
5	 * non-digit characters. Used to derive an owner's {@code checkDigit} from their {@code customerCode}.
6	 */
7	public final class CheckDigit {
8	
9	    private CheckDigit() {
10	    }
11	
12	    public static int luhn(String s) {
13	        int sum = 0;
14	        boolean dbl = true;
15	        for (int i = s.length() - 1; i >= 0; i--) {
16	            char c = s.charAt(i);
17	            if (c < '0' || c > '9') {
18	                continue;
19	            }
20	            int d = c - '0';
21	            if (dbl) {
22	                d *= 2;
23	                if (d > 9) {
24	                    d -= 9;
25	                }
26	            }
27	            sum += d;
28	            dbl = !dbl;
29	        }
30	        return (10 - (sum % 10)) % 10;
31	    }
32	}
