16	package org.springframework.samples.petclinic.util;
17	
18	import java.time.LocalDate;
19	import java.time.Month;
20	
21	/**
22	 * Fiscal-year arithmetic: the fiscal year runs 1 July to 30 June and is named by the calendar year
23	 * in which it ends, so a July date belongs to the following year's fiscal year.
24	 */
25	public final class FiscalYear {
26	
27	    private FiscalYear() {
28	    }
29	
30	    /** The fiscal year a date falls in (e.g. 2027 for 2 July 2026). */
31	    public static int of(LocalDate date) {
32	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
33	    }
34	
35	    /** The fiscal year of a date formatted {@code 'FY<YY>'} (last two digits). */
36	    public static String label(LocalDate date) {
37	        return String.format("FY%02d", of(date) % 100);
38	    }
39	
40	    /** Whole fiscal years elapsed from one date to another. */
41	    public static int elapsed(LocalDate from, LocalDate to) {
42	        return of(to) - of(from);
43	    }
44	}
