41	            sb.append(String.format("%02x", b));
42	        }
43	        return sb.toString();
44	    }
45	
46	    /** The American Soundex code (a letter followed by three digits) for the given name, or empty. */
47	    static String soundex(String name) {
48	        String letters = name == null ? "" : name.toUpperCase().replaceAll("[^A-Z]", "");
49	        if (letters.isEmpty()) {
50	            return "";
51	        }
52	        StringBuilder sb = new StringBuilder().append(letters.charAt(0));
53	        char prev = SOUNDEX_CODES.charAt(letters.charAt(0) - 'A');
54	        for (int i = 1; i < letters.length() && sb.length() < 4; i++) {
55	            char c = letters.charAt(i);
56	            char code = SOUNDEX_CODES.charAt(c - 'A');
57	            if (code != '0' && code != prev) {
58	                sb.append(code);
59	            }
60	            if (c != 'H' && c != 'W') {
61	                prev = code;
62	            }
63	        }
64	        while (sb.length() < 4) {
65	            sb.append('0');
66	        }
67	        return sb.toString();
68	    }
69	
70	    private static byte[] sha256(String value) {
71	        try {
72	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
73	        } catch (NoSuchAlgorithmException e) {
74	            throw new IllegalStateException(e);
75	        }
76	    }
77	}
