33	    /**
34	     * Derives the household identifier for the response: the deterministic {@link Household#id} over
35	     * the owner's last name and postcode, so members of one household always report the same id.
36	     * Non-persistent, so it never affects storage or the request payload.
37	     */
38	    @AfterMapping
39	    default void deriveHouseholdId(Owner owner, @MappingTarget OwnerDto ownerDto) {
40	        ownerDto.setHouseholdId(Household.id(owner.getLastName(), owner.getPostcode()));
41	    }
42	
43	    /**
44	     * Derives 'identityKey' for the response: the single duplicate-detection key from
45	     * {@link OwnerIdentity#key(Owner)}. Non-persistent, so it never affects storage or the request payload.
46	     */
47	    @AfterMapping
48	    default void deriveIdentityKey(Owner owner, @MappingTarget OwnerDto ownerDto) {
49	        ownerDto.setIdentityKey(OwnerIdentity.key(owner));
50	    }
51	
52	    /**
53	     * Derives 'locality' for the response: the REGION segment of the owner's {@code customerCode}
54	     * (the '<REGION>-<HASH8>' identity), falling back to {@link LocalityResolver#resolve} when no
55	     * customerCode is present. Non-persistent, so it never affects storage or the request payload.
56	     */
57	    @AfterMapping
58	    default void deriveLocality(Owner owner, @MappingTarget OwnerDto ownerDto) {
59	        String code = owner.getCustomerCode();
60	        int dash = code == null ? -1 : code.indexOf('-');
61	        ownerDto.setLocality(dash > 0 ? code.substring(0, dash)
62	            : LocalityResolver.resolve(owner.getCity(), owner.getPostcode()));
63	    }
64	
65	    /** Fixed region-to-timezone table, as IANA names. */
66	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
67	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
68	
69	    /**
70	     * Derives 'timezone' for the response: the IANA name for the owner's region (the already-derived
71	     * {@code locality}) from {@link #REGION_TIMEZONE}, left unset when the region has no entry.
72	     * Non-persistent, so it never affects storage or the request payload.
73	     */
74	    @AfterMapping
75	    default void deriveTimezone(Owner owner, @MappingTarget OwnerDto ownerDto) {
76	        ownerDto.setTimezone(REGION_TIMEZONE.get(ownerDto.getLocality()));
77	    }
78	
79	    /**
80	     * Derives 'contactPreference' for the response: 'EMAIL' when the owner has an email address,
81	     * otherwise 'PHONE'. Non-persistent, so it never affects storage or the request payload.
82	     */
83	    @AfterMapping
84	    default void deriveContactPreference(Owner owner, @MappingTarget OwnerDto ownerDto) {
85	        String email = owner.getEmail();
86	        ownerDto.setContactPreference(email == null || email.isBlank() ? "PHONE" : "EMAIL");
87	    }
88	
89	    /**
90	     * Derives 'ageBand' for the response from the owner's birth date, measured against the
91	     * registration date: 'MINOR' when under 18, 'ADULT' for 18-64 and 'SENIOR' for 65+. Left
92	     * unset when no birth date is supplied. Non-persistent, so it never affects storage.
93	     */
94	    @AfterMapping
95	    default void deriveAgeBand(Owner owner, @MappingTarget OwnerDto ownerDto) {
96	        java.time.LocalDate birthDate = owner.getBirthDate();
97	        if (birthDate == null) {
98	            return;
99	        }
100	        int years = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
101	        ownerDto.setAgeBand(years < 18 ? "MINOR" : years < 65 ? "ADULT" : "SENIOR");
102	    }
103	
104	    /**
105	     * Derives 'telephoneDisplay' for the response: the stored E.164 'telephone' formatted for
106	     * humans by {@link org.springframework.samples.petclinic.util.TelephoneDisplay#format}. Raw
107	     * 'telephone' is left untouched. Non-persistent, so it never affects storage or the request payload.
108	     */
109	    @AfterMapping
110	    default void deriveTelephoneDisplay(Owner owner, @MappingTarget OwnerDto ownerDto) {
111	        ownerDto.setTelephoneDisplay(
112	            org.springframework.samples.petclinic.util.TelephoneDisplay.format(owner.getTelephone()));
113	    }
