27	/**
28	 * Rejects a newly created owner whose whole {@link OwnerIdentity#key(Owner) identity key} — the
29	 * normalized telephone, email and household id — exactly matches an existing owner's. This single
30	 * key subsumes the former separate telephone, email and household duplicate checks. Updates to an
31	 * existing owner keep their own identity and are left untouched.
32	 */
33	@Aspect
34	@Component
35	public class OwnerIdentityUniquenessAspect {
36	
37	    private final OwnerRepository ownerRepository;
38	
39	    public OwnerIdentityUniquenessAspect(OwnerRepository ownerRepository) {
40	        this.ownerRepository = ownerRepository;
41	    }
42	
43	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
44	    public void rejectDuplicateIdentity(Owner owner) {
45	        if (!owner.isNew()) {
46	            return;
47	        }
48	        String identityKey = OwnerIdentity.key(owner);
49	        boolean taken = ownerRepository.findAll().stream()
50	            .filter(existing -> !existing.isDeleted())
51	            .anyMatch(existing -> identityKey.equals(OwnerIdentity.key(existing)));
52	        if (taken) {
53	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Another owner already has this identity");
54	        }
55	    }
56	}
